import type { Booking } from '@prisma/client';
import { bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { MINUTE_IN_MS, parseInstant } from '../../shared/time.js';
import * as roomRepository from '../rooms/repository.js';
import * as repository from './repository.js';
import { BOOKING_CANCELLED, DEFAULT_SLOT_DURATION_MINUTES } from './schema.js';
import type {
  AvailabilityInput,
  CreateBookingInput,
  ListBookingsInput,
  UpdateBookingInput,
} from './schema.js';

const SUGGESTION_LIMIT = 3;
const SUGGESTION_WINDOW_MS = 24 * 60 * 60 * 1000;

interface Slot {
  startsAt: Date;
  endsAt: Date;
}

function computeFreeSlots(
  bookings: Array<{ startsAt: Date; endsAt: Date }>,
  from: Date,
  to: Date,
  durationMinutes: number,
): Slot[] {
  const minDurationMs = durationMinutes * MINUTE_IN_MS;
  const slots: Slot[] = [];
  let cursor = from;

  for (const booking of bookings) {
    const gapEnd = booking.startsAt > cursor ? booking.startsAt : cursor;
    if (gapEnd.getTime() - cursor.getTime() >= minDurationMs) {
      slots.push({ startsAt: cursor, endsAt: gapEnd });
    }
    if (booking.endsAt > cursor) {
      cursor = booking.endsAt;
    }
  }

  if (to.getTime() - cursor.getTime() >= minDurationMs) {
    slots.push({ startsAt: cursor, endsAt: to });
  }

  return slots;
}

async function suggestAlternatives(
  roomId: string,
  after: Date,
  durationMinutes: number,
): Promise<Slot[]> {
  const to = new Date(after.getTime() + SUGGESTION_WINDOW_MS);
  const bookings = await repository.listActiveForRoom(roomId, after, to);
  return computeFreeSlots(bookings, after, to, durationMinutes).slice(0, SUGGESTION_LIMIT);
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const startsAt = parseInstant(input.startsAt);
  const endsAt = parseInstant(input.endsAt);

  const conflict = await repository.findOverlapping(input.roomId, startsAt, endsAt);
  if (conflict) {
    const requestedMinutes = Math.round((endsAt.getTime() - startsAt.getTime()) / MINUTE_IN_MS);
    const suggestions = await suggestAlternatives(input.roomId, startsAt, requestedMinutes);
    throw bookingConflict(conflict.id, suggestions);
  }

  return repository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
}

export async function getRoomAvailability(
  query: AvailabilityInput,
): Promise<{ roomId: string; slots: Slot[] }> {
  const room = await roomRepository.findById(query.roomId);
  if (!room) {
    throw notFound('Room');
  }

  const from = parseInstant(query.from);
  const to = parseInstant(query.to);
  if (to <= from) {
    throw validationFailed('"to" must be after "from"', { from: query.from, to: query.to });
  }

  const durationMinutes = query.durationMinutes ?? DEFAULT_SLOT_DURATION_MINUTES;
  const bookings = await repository.listActiveForRoom(query.roomId, from, to);
  return { roomId: query.roomId, slots: computeFreeSlots(bookings, from, to, durationMinutes) };
}

